@OptIn(ExperimentalAtomicApi::class)
class VersionedSlot(private var v: AtomicInt = AtomicInt(0)) {
    // returns true when this caller committed version `expected`
    fun tryCommit(expected: Int): Boolean =
        v.compareAndSet(expected, expected + 1)
    // caller re-reads and recomputes when false
}

